import{_ as t,o as s,c as a,a6 as n}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"变量","description":"$uri 与 $request_uri 的关键差异、$host 的三级回退、动态变量族与求值时机。","frontmatter":{"title":"变量","description":"$uri 与 $request_uri 的关键差异、$host 的三级回退、动态变量族与求值时机。","source":"https://daiw.org/manual/nginx/variables"},"headers":[],"relativePath":"manual/tools/nginx/variables.md","filePath":"manual/tools/nginx/variables.md"}'),r={name:"manual/tools/nginx/variables.md"};function o(d,e,p,c,i,l){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h1><p>变量是 nginx 配置里唯一的「数据」。用错变量是仅次于<a href="/Front2Full/manual/tools/nginx/contexts">继承</a>与 <a href="/Front2Full/manual/tools/nginx/location">location</a> 的第三大错误源。</p><h2 id="uri-vs-request-uri" tabindex="-1"><code>$uri</code> vs <code>$request_uri</code> <a class="header-anchor" href="#uri-vs-request-uri" aria-label="Permalink to &quot;\`$uri\` vs \`$request_uri\`&quot;">​</a></h2><p>最重要的一对，官方定义：</p><blockquote><p><strong><code>$uri</code></strong> — current URI in request, <strong>normalized</strong>. The value of <code>$uri</code> <strong>may change during request processing</strong>, e.g. when doing internal redirects, or when using index files.</p><p><strong><code>$request_uri</code></strong> — <strong>full original</strong> request URI (<strong>with arguments</strong>)</p></blockquote><table tabindex="0"><thead><tr><th></th><th><code>$uri</code></th><th><code>$request_uri</code></th></tr></thead><tbody><tr><td>是否含查询串</td><td><strong>否</strong></td><td><strong>是</strong></td></tr><tr><td>是否归一化</td><td><strong>是</strong>（解码 <code>%XX</code>、合并 <code>//</code>、消解 <code>.</code>/<code>..</code>）</td><td><strong>否</strong>，原样</td></tr><tr><td>处理中是否变化</td><td><strong>会变</strong>（内部重定向、index）</td><td><strong>不变</strong></td></tr></tbody></table><p>对请求 <code>GET /a//b/../c.html?x=1</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$uri          = /a/c.html          归一化，无参数</span></span>
<span class="line"><span>$request_uri  = /a//b/../c.html?x=1  原始，含参数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>重定向时该用哪个？</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>return 301 https://$host$request_uri;   # ✅ 保留查询参数与原始形式</span></span>
<span class="line"><span>return 301 https://$host$uri;           # ❌ 丢掉 ?x=1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>HTTP→HTTPS 跳转必须用 <code>$request_uri</code>，否则所有带查询参数的请求都会丢参数。这是极高频的误配。</p><p>反过来，做<strong>路径判断</strong>时要用 <code>$uri</code>——它已归一化，不会被 <code>//</code>、<code>%2e%2e</code> 这类编码绕过。用 <code>$request_uri</code> 做安全判断存在绕过风险。</p><p><code>$document_uri</code> 是 <code>$uri</code> 的别名，二者完全相同。</p><h2 id="host-的三级回退" tabindex="-1">$host 的三级回退 <a class="header-anchor" href="#host-的三级回退" aria-label="Permalink to &quot;$host 的三级回退&quot;">​</a></h2><p>官方定义写得很精确：</p><blockquote><p><strong>in this order of precedence</strong>: host name from the <strong>request line</strong>, or host name from the <strong>&quot;Host&quot; request header</strong> field, or the <strong>server name</strong> matching a request</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 请求行里的主机名（absolute-form 请求，见 HTTP/1.1 请求行）</span></span>
<span class="line"><span>2. Host 请求头</span></span>
<span class="line"><span>3. 匹配到的 server_name</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>关键推论：<strong><code>$host</code> 永远有值</strong>（最差回退到 <code>server_name</code>），而 <code>$http_host</code> 是<strong>原样的 Host 头</strong>，可能为空。</p><table tabindex="0"><thead><tr><th>变量</th><th>来源</th><th>可能为空</th><th>是否含端口</th></tr></thead><tbody><tr><td><code>$host</code></td><td>三级回退，<strong>小写</strong></td><td>否</td><td><strong>否</strong></td></tr><tr><td><code>$http_host</code></td><td>Host 头原样</td><td><strong>是</strong></td><td><strong>是</strong>（如果客户端发了）</td></tr><tr><td><code>$server_name</code></td><td>匹配到的 server_name</td><td>否</td><td>否</td></tr></tbody></table><p><code>$host</code> 会<strong>转小写并去掉端口</strong>，<code>$http_host</code> 不会。做重定向时用 <code>$host</code> 更安全。</p><h2 id="动态变量族" tabindex="-1">动态变量族 <a class="header-anchor" href="#动态变量族" aria-label="Permalink to &quot;动态变量族&quot;">​</a></h2><p>三个「前缀 + 名字」的变量族，可以取任意字段：</p><table tabindex="0"><thead><tr><th>形式</th><th>取什么</th><th>例</th></tr></thead><tbody><tr><td><code>$http_名字</code></td><td><strong>请求</strong>头</td><td><code>$http_user_agent</code>、<code>$http_x_forwarded_for</code></td></tr><tr><td><code>$sent_http_名字</code></td><td><strong>响应</strong>头</td><td><code>$sent_http_content_type</code></td></tr><tr><td><code>$arg_名字</code></td><td>查询参数</td><td><code>$arg_page</code>（对应 <code>?page=2</code>）</td></tr><tr><td><code>$cookie_名字</code></td><td>Cookie</td><td><code>$cookie_session</code></td></tr></tbody></table><p><strong>转换规则</strong>：字段名转小写，<code>-</code> 换成 <code>_</code>。<code>X-Forwarded-For</code> → <code>$http_x_forwarded_for</code>。</p><p>另有 <code>$upstream_http_名字</code>（上游响应头）等，见<a href="/Front2Full/manual/tools/nginx/proxy">代理章节</a>。</p><h2 id="常用变量速查" tabindex="-1">常用变量速查 <a class="header-anchor" href="#常用变量速查" aria-label="Permalink to &quot;常用变量速查&quot;">​</a></h2><h3 id="请求" tabindex="-1">请求 <a class="header-anchor" href="#请求" aria-label="Permalink to &quot;请求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>官方定义</th></tr></thead><tbody><tr><td><code>$request_method</code></td><td>request method, usually <code>GET</code> or <code>POST</code></td></tr><tr><td><code>$scheme</code></td><td>request scheme, <code>http</code> or <code>https</code></td></tr><tr><td><code>$https</code></td><td><code>on</code> if connection operates in SSL mode, or an <strong>empty string</strong> otherwise</td></tr><tr><td><code>$args</code> / <code>$query_string</code></td><td>arguments in the request line（两者相同）</td></tr><tr><td><code>$is_args</code></td><td><code>?</code> if a request line has arguments, or an <strong>empty string</strong> otherwise</td></tr><tr><td><code>$remote_addr</code></td><td>client address</td></tr><tr><td><code>$remote_port</code></td><td>client port</td></tr><tr><td><code>$remote_user</code></td><td>user name supplied with the Basic authentication</td></tr></tbody></table><p>注意 <strong><code>$https</code> 在非 TLS 时是空串而不是 <code>off</code></strong>——判断时应写 <code>if ($https = &quot;&quot;)</code> 或直接用 <code>$scheme</code>。</p><p><code>$is_args</code> 专门配合拼接使用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rewrite ^ /new$is_args$args;   # 有参数才带 ?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to &quot;路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>官方定义</th></tr></thead><tbody><tr><td><code>$request_filename</code></td><td>file path for the current request, based on the <code>root</code> or <code>alias</code> directives, and the request URI</td></tr><tr><td><code>$document_root</code></td><td><code>root</code> or <code>alias</code> directive&#39;s value for the current request</td></tr><tr><td><code>$realpath_root</code></td><td>absolute pathname […] <strong>with all symbolic links resolved</strong></td></tr></tbody></table><p><code>$realpath_root</code> 与 <code>$document_root</code> 的区别就是<strong>符号链接是否解析</strong>。给 PHP-FPM 传 <code>DOCUMENT_ROOT</code> 时，用哪个取决于应用是否依赖真实路径（OPcache 在符号链接部署下常需要 <code>$realpath_root</code>）。</p><h3 id="服务端与响应" tabindex="-1">服务端与响应 <a class="header-anchor" href="#服务端与响应" aria-label="Permalink to &quot;服务端与响应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>官方定义</th></tr></thead><tbody><tr><td><code>$server_name</code></td><td>name of the server which accepted a request</td></tr><tr><td><code>$server_port</code></td><td>port of the server which accepted a request</td></tr><tr><td><code>$hostname</code></td><td>host name（<strong>机器主机名</strong>，不是请求的）</td></tr><tr><td><code>$status</code></td><td>response status（1.3.2, 1.2.2 起）</td></tr><tr><td><code>$body_bytes_sent</code></td><td>number of bytes sent to a client, <strong>not counting the response header</strong></td></tr><tr><td><code>$request_time</code></td><td>request processing time in seconds with a <strong>milliseconds resolution</strong>（1.3.9, 1.2.6 起）; time elapsed since the <strong>first bytes were read from the client</strong></td></tr></tbody></table><p><code>$hostname</code> 是<strong>运行 nginx 那台机器的主机名</strong>，与请求内容无关。想要请求的主机名用 <code>$host</code>。这两个名字太像，容易写错。</p><p><code>$request_time</code> 的计时起点是<strong>读到客户端第一个字节</strong>——包含了读请求体的时间。所以慢客户端上传大文件会让这个值很大，但那不是服务端慢。区分服务端耗时要看 <code>$upstream_response_time</code>（见<a href="/Front2Full/manual/tools/nginx/proxy">代理章节</a>）。</p><h2 id="变量的求值时机" tabindex="-1">变量的求值时机 <a class="header-anchor" href="#变量的求值时机" aria-label="Permalink to &quot;变量的求值时机&quot;">​</a></h2><p>nginx 变量是<strong>惰性求值</strong>的：用到才算，且多数会缓存本次请求的结果。</p><p>两个实际影响：</p><p><strong>一、<code>$uri</code> 在内部重定向后会变。</strong> <a href="/Front2Full/manual/tools/nginx/root-alias"><code>try_files</code></a>、<code>index</code>、<code>rewrite</code> 都会改写 <code>$uri</code>。所以日志里记的 <code>$uri</code> 可能不是客户端请求的那个——日志要记原始路径应该用 <code>$request_uri</code>。</p><p><strong>二、<code>map</code> 定义的变量在首次使用时才计算。</strong> 见 <a href="/Front2Full/manual/tools/nginx/map-geo">map 与 geo</a>。</p><h2 id="自定义变量" tabindex="-1">自定义变量 <a class="header-anchor" href="#自定义变量" aria-label="Permalink to &quot;自定义变量&quot;">​</a></h2><p><code>set</code> 指令（属于 <code>ngx_http_rewrite_module</code>）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set $my_var &quot;value&quot;;</span></span>
<span class="line"><span>set $combined &quot;$host$request_uri&quot;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>注意它的执行时机受 rewrite 阶段影响，详见 <a href="/Front2Full/manual/tools/nginx/rewrite">rewrite 与 if</a>。</p><h2 id="一个综合例子" tabindex="-1">一个综合例子 <a class="header-anchor" href="#一个综合例子" aria-label="Permalink to &quot;一个综合例子&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># HTTP → HTTPS：必须用 $request_uri</span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    listen 80;</span></span>
<span class="line"><span>    server_name example.com;</span></span>
<span class="line"><span>    return 301 https://$host$request_uri;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    server_name example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 按查询参数分流</span></span>
<span class="line"><span>    location /search {</span></span>
<span class="line"><span>        if ($arg_debug = &quot;1&quot;) {</span></span>
<span class="line"><span>            return 403;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        proxy_pass http://backend;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 传给上游的标准头</span></span>
<span class="line"><span>    location /api/ {</span></span>
<span class="line"><span>        proxy_set_header Host              $host;</span></span>
<span class="line"><span>        proxy_set_header X-Real-IP         $remote_addr;</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-Proto $scheme;</span></span>
<span class="line"><span>        proxy_pass http://backend;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><p><code>$proxy_add_x_forwarded_for</code> 来自 proxy 模块——它是「原有 <code>X-Forwarded-For</code> 头 + <code>$remote_addr</code>」的拼接，正是<a href="https://daiw.org/manual/http11/proxy-fields" target="_blank" rel="noreferrer">逐跳追加</a>的实现。</p><p>下一篇：<a href="/Front2Full/manual/tools/nginx/proxy">proxy 反向代理</a>。</p>`,51)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
